// Mechanical coordinator: integrates worker self-reviewed packets; no cross-worker semantic approval.
const fs=require('fs'),z=require('zlib'),crypto=require('crypto'),assert=require('assert/strict');
const root='docs/ssw-workspace/agriculture/parallel-completion-20261103/',ld='docs/ssw-workspace/source-coverage-v2/',lp=ld+'agriculture.json',cp='src/data/agriculture/reader-moisture-checks.json';
const read=p=>JSON.parse(fs.readFileSync(p)),write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n'),hash=v=>crypto.createHash('sha256').update(JSON.stringify(v)).digest('hex'),bytes=b=>crypto.createHash('sha256').update(b).digest('hex');
const ledger=read(lp),beforeLedger=structuredClone(ledger),checks=read(cp),oldChecks=structuredClone(checks),additions=[],proposals=[];const receipt=root+'integration/receipt.json';
function append(row,lane){assert(!checks.checks.some(c=>c.id===row.id),'Already integrated '+row.id);const locales=['en','vi','id','zh-CN','zh-TW','hi','bn','ne','my','th','km','tl'];assert.deepEqual(Object.keys(row.translations).sort(),locales.sort());for(const f of ['prompt','modelAnswer',...(row.teachingJa?['teaching']:[])]){assert.equal(row[f+'Ruby'].map(x=>x.text).join(''),row[f+'Ja']);for(const token of row[f+'Ruby'])if(/[\p{Script=Han}々]/u.test(token.text))assert(token.readingKana,'Missing reading '+row.id);for(const lc of locales)assert(row.translations[lc][f]?.trim(),'Missing '+lc+'/'+f);}checks.checks.push(row);additions.push({lane,id:row.id,index:checks.checks.length-1});}
const soil=read(root+'soil/proposal.json');for(const p of soil.patches)append(p.value,'soil');
const facility=read(root+'facility/patch-proposal.json');for(const row of facility.patch.newReaderChecks)append(row,'facility');
const rice=read(root+'rice/patch-proposal.json');for(const p of rice.changes)append(p.after,'rice');
const veg=read(root+'vegetables/reader-additions.json');for(const row of veg.rows)append(row,'vegetables');
// Worker-owned source-checked unit replacements with before-value guards.
for(const [lane,packet]of [['facility',facility],['rice',rice]])for(const p of packet.ledgerUnitProposals||[]){const i=ledger.knowledgeUnits.findIndex(u=>u.knowledgeId===p.knowledgeId);assert(i>=0);assert.equal(hash(ledger.knowledgeUnits[i]),p.beforeSha256);assert(!['covered_ai','duplicate','excluded'].includes(ledger.knowledgeUnits[i].status));ledger.knowledgeUnits[i]=p.after;proposals.push({lane,id:p.knowledgeId,before:beforeLedger.knowledgeUnits.find(u=>u.knowledgeId===p.knowledgeId),afterStatus:p.after.status});}
function ev(path,ptr,note){let v=path===cp?checks:read(path);for(const k of ptr.slice(1).split('/'))v=v[k];return{path,jsonPointer:ptr,sha256:hash(v),sha256Mode:'json-value',relation:'direct',semanticReviewed:true,reviewNote:note};}
for(const p of soil.canonicalUpdates){const i=ledger.knowledgeUnits.findIndex(u=>u.knowledgeId===p.knowledgeId);assert(i>=0&&ledger.knowledgeUnits[i].status==='candidate');const before=structuredClone(ledger.knowledgeUnits[i]),patch=soil.patches[p.teachingEvidenceFromPatch],ci=checks.checks.findIndex(c=>c.id===p.assessmentEvidenceFromAppendedCheck);assert(ci>=0);const te=ev('src/data/agriculture/lessons.ja.json',patch.teachingPointer,'Soil worker self-read original rendered clause and current teaching, including stated limits.');assert.equal(te.sha256,patch.teachingSha256);Object.assign(ledger.knowledgeUnits[i],{statementJa:p.statementJa,sourceRefs:p.sourceRefs,conditionsJa:p.conditionsJa,after:{teaching:'present',assessment:'present'},teachingEvidence:[te],assessmentEvidence:[ev(cp,'/checks/'+ci,'Soil worker-authored retrieval directly elicits the bounded source facet; all12 direct locale prompts use revision-bound answers.')],expressionReview:{status:'independent_ai_checked',note:'Existing independently authored explanation retained; new original retrieval prompt self-checked by soil worker.'},sourceReview:{status:'self_checked_ai',conditionsChecked:true,reviewRef:root+'soil/receipt.json'},status:'covered_ai',unresolved:[]});proposals.push({lane:'soil',id:p.knowledgeId,before,afterStatus:'covered_ai'});}
for(const p of read(root+'rice/source-acceptance.json').units){const i=ledger.knowledgeUnits.findIndex(u=>u.knowledgeId===p.knowledgeId);assert(i>=0);assert.deepEqual(ledger.knowledgeUnits[i],p.before);ledger.knowledgeUnits[i]=p.after;proposals.push({lane:'rice',id:p.knowledgeId,before:p.before,afterStatus:p.after.status});}
for(const p of read(root+'fruit/unit-updates.json').updates){const i=ledger.knowledgeUnits.findIndex(u=>u.knowledgeId===p.knowledgeId);assert(i>=0);assert.equal(hash(ledger.knowledgeUnits[i]),p.beforeSha256);const before=structuredClone(ledger.knowledgeUnits[i]);Object.assign(ledger.knowledgeUnits[i],p.patch);proposals.push({lane:'fruit',id:p.knowledgeId,before,afterStatus:ledger.knowledgeUnits[i].status});}
for(const p of read(root+'soil/proposal-next.json').canonicalUpdates){const i=ledger.knowledgeUnits.findIndex(u=>u.knowledgeId===p.knowledgeId);assert(i>=0);assert.equal(hash(ledger.knowledgeUnits[i]),p.beforeUnitSha256);const before=structuredClone(ledger.knowledgeUnits[i]);Object.assign(ledger.knowledgeUnits[i],{statementJa:p.statementJa,sourceRefs:p.sourceRefs,conditionsJa:p.conditionsJa,teachingEvidence:p.teachingEvidence,assessmentEvidence:p.assessmentEvidence,expressionReview:p.expressionReview,sourceReview:p.sourceReview,after:{teaching:'present',assessment:'present'},status:'covered_ai',unresolved:[],previousSourceRefsParallel20261103:before.sourceRefs});proposals.push({lane:'soil',id:p.knowledgeId,before,afterStatus:'covered_ai'});}
for(const p of read(root+'vegetables/unit-updates.json').proposedUpdates){const i=ledger.knowledgeUnits.findIndex(u=>u.knowledgeId===p.knowledgeId);assert(i>=0);assert.equal(hash(ledger.knowledgeUnits[i]),p.beforeSha256);ledger.knowledgeUnits[i]=p.after;proposals.push({lane:'vegetables',id:p.knowledgeId,before:p.before,afterStatus:p.after.status});}
const arts={};for(const s of ledger.sources){const p=ld+`agriculture-${s.sourceId}-regions.json.gz`;arts[s.sourceId]=JSON.parse(z.gunzipSync(fs.readFileSync(p)));}
for(const {id}of proposals){const unit=ledger.knowledgeUnits.find(u=>u.knowledgeId===id);for(const ref of unit.sourceRefs){assert(ref.elementIds.length,'Empty source ref '+id);const pg=arts[ref.sourceId].pages.find(p=>p.pdfPage===ref.pdfPage);for(const eid of ref.elementIds){const el=pg.elements.find(e=>e.elementId===eid);assert(el,'Unknown element '+eid);el.classification='knowledge';el.knowledgeIds=[...new Set([...el.knowledgeIds,id])];el.reason=null;}}}
for(const {id}of proposals){const u=ledger.knowledgeUnits.find(u=>u.knowledgeId===id);for(const r of u.sourceRefs){const p=ledger.pages.find(p=>p.sourceId===r.sourceId&&p.pdfPage===r.pdfPage);p.regionCensus.status='visually_reviewed';p.regionCensus.visualReviewRef=u.sourceReview.reviewRef;if(p.semanticInventory.status==='pending')p.semanticInventory={status:'partial',reviewRef:u.sourceReview.reviewRef};if(p.disposition==='unclassified')p.disposition='mixed';}}
// Reconcile reciprocal links without dropping unrelated prior assignments.
for(const pg of ledger.pages)pg.knowledgeIds=ledger.knowledgeUnits.filter(u=>u.sourceRefs.some(r=>r.sourceId===pg.sourceId&&r.pdfPage===pg.pdfPage)).map(u=>u.knowledgeId);
for(const s of ledger.sources){const p=ld+`agriculture-${s.sourceId}-regions.json.gz`,buf=z.gzipSync(JSON.stringify(arts[s.sourceId]),{mtime:0});fs.writeFileSync(p,buf);for(const pg of ledger.pages.filter(p=>p.sourceId===s.sourceId))pg.regionCensus.sha256=bytes(buf);}
for(const u of beforeLedger.knowledgeUnits.filter(u=>['covered_ai','duplicate','excluded'].includes(u.status)))assert.deepEqual(ledger.knowledgeUnits.find(v=>v.knowledgeId===u.knowledgeId),u,'Prior accepted unit changed');for(const c of oldChecks.checks)assert.deepEqual(checks.checks.find(v=>v.id===c.id),c);
write(cp,checks);write(lp,ledger);
const fixture=read(root+'daily/test-sentinel-patch.json');let text=fs.readFileSync(fixture.target,'utf8');assert.equal(text.split(fixture.before).length-1,fixture.expectedOccurrences);fs.writeFileSync(fixture.target,text.replace(fixture.before,fixture.after));
write(receipt,{schemaVersion:1,status:'INTEGRATED_PENDING_VALIDATION',canonicalLedger:lp,workerSemanticCrossReview:false,additions,unitChanges:proposals,coveredBefore:beforeLedger.knowledgeUnits.filter(u=>u.status==='covered_ai').length,coveredAfter:ledger.knowledgeUnits.filter(u=>u.status==='covered_ai').length,sourceCoveragePercent:null,wholeSourceKnowledgeCovered:false,priorAcceptedUnitsPreserved:true,priorChecksPreserved:true,nativeReviewed:false,domainReviewed:false,physicalDeviceTested:false,learnerDurationMeasured:false});console.log(JSON.stringify({newChecks:additions.length,unitChanges:proposals.length,covered:ledger.knowledgeUnits.filter(u=>u.status==='covered_ai').length}));
